  const patches = [path.join(fork, 'patches/baseline/0001-foundation-baseline.patch'),
    ...fs.readdirSync(path.join(fork, 'patches')).filter(f => /^\d{4}-.*\.patch$/.test(f)).sort().map(f => path.join(fork, 'patches', f))];
  const registered = registeredPrefs(patches);
